static int g_owner = 1;
static int g_acl_valid_ret = 0;
static int g_set_acl_ret = 0;
static int g_set_acl_calls = 0;
static struct posix_acl *g_set_acl_acl = NULL;
static int g_set_acl_type = -1;

int inode_owner_or_capable(struct inode *inode) { (void)inode; return g_owner; }
int posix_acl_valid(const struct posix_acl *acl) { (void)acl; return g_acl_valid_ret; }
static int fake_set_acl(struct inode *inode, struct posix_acl *acl, int type) {
	(void)inode; g_set_acl_calls++; g_set_acl_acl = acl; g_set_acl_type = type; return g_set_acl_ret;
}

