		return -EPERM;

	if (acl) {
		int ret = posix_acl_valid(acl);
		if (ret)
			return ret;
	}
	return inode->i_op->set_acl(inode, acl, type);
}
EXPORT_SYMBOL(set_posix_acl);
/* ==== END verbatim set_posix_acl ==== */

static struct inode_operations ops_yes = { .set_acl = fake_set_acl };
static struct inode_operations ops_no  = { .set_acl = NULL };

